per {\r\n  position: relative;\r\n  display: block;\r\n  width: auto;\r\n  max-width: 100%; // not required for horizontal scroll to trigger\r\n  height: 100%; // required for horizontal native scrollbar to not appear if parent is taller than natural height\r\n  max-height: 100%; // needed for vertical scroll to trigger\r\n  direction: inherit;\r\n  // box-sizing: border-box;\r\n  scrollbar-width: none;\r\n  // -ms-overflow-style: none;\r\n\r\n  &::-webkit-scrollbar {\r\n    display: none;\r\n    width: 0;\r\n    height: 0;\r\n  }\r\n}\r\n\r\n.content {\r\n  position: relative;\r\n\r\n  .dragging & {\r\n    user-select: none;\r\n    pointer-events: none;\r\n    -webkit-touch-callout: none;\r\n  }\r\n\r\n  // &::before, &::after {\r\n  //   content: '';\r\n  //   display: table;\r\n  // }\r\n}\r\n\r\n.placeholder {\r\n  width: 100%;\r\n  max-width: 100%;\r\n  height: 100%;\r\n  pointer-events: none;\r\n}\r\n\r\n.heightObserverWrapper {\r\n  position: relative;\r\n  flex-grow: inherit;\r\n  flex-shrink: 0;\r\n  flex-basis: 0;\r\n  float: left;\r\n  width: 100%;\r\n  max-width: 1px;\r\n  height: 100%;\r\n  max-height: 1px;\r\n  @include spacing.margin-none;\r\n  @include spacing.padding-none;\r\n  box-sizing: inherit;\r\n  overflow: hidden;\r\n  z-index: -1;\r\n  pointer-events: none;\r\n}\r\n\r\n.heightObserver {\r\n  @include position.absolute-anchor($x: 0, $y: 0);\r\n  display: block;\r\n  width: 1000%;\r\n  min-width: 1px;\r\n  height: 1000%;\r\n  min-height: 1px;\r\n  opacity: 0;\r\n  box-sizing: inherit;\r\n  overflow: hidden;\r\n  z-index: -1;\r\n  pointer-events: none;\r\n}\r\n\r\n.track {\r\n  @include position.absolute-anchor($x: 0, $y: 0, $x-prop: right, $y-prop: bottom);\r\n  overflow: hidden;\r\n  z-index: 1;\r\n  pointer-events: none;\r\n\r\n  &.horizontal {\r\n    left: 0;\r\n    height: 11px;\r\n  }\r\n\r\n  &.vertical {\r\n    top: 0;\r\n    width: 11px;\r\n  }\r\n\r\n  // rtl support\r\n  [data-simplebar-direction='rtl'] &.vertical {\r\n    right: aut