ins/spacing';\r\n@use 'mixins/transition';\r\n\r\n.container {\r\n  position: relative;\r\n  @include spacing.padding-xy($x: 35px, $y: 12px);\r\n  @include font.apply(fonts.$primary, ( font-weight: 300 ));\r\n  font-size: 14px;\r\n  color: colors.$transparent;\r\n  letter-spacing: 3px;\r\n  text-align: center;\r\n  text-transform: uppercase;\r\n  background: linear-gradient(75deg, #4A9AC7 5%, #F148CC 95%) 0 0 / 200% 100%;\r\n  background-clip: text;\r\n  border-radius: 100px;\r\n  @include transition.apply(color, box-shadow);\r\n\r\n  &.light {\r\n    box-shadow: (\r\n      0 0 1px color.alpha(colors.$black, 0.4),\r\n      0 0 4px color.alpha(colors.$gray-dark, 0.24),\r\n    );\r\n\r\n    &.mina {\r\n      box-shadow: (\r\n        0 0 1px color.alpha(#770629, 0.4),\r\n        0 0 4px color.alpha(#D76D8E, 0.24),\r\n      );\r\n    }\r\n  }\r\n\r\n  &.dark {\r\n    box-shadow: (\r\n      0 0 1px color.alpha(colors.$white, 0.4),\r\n      0 0 12px color.alpha(colors.$black, 0.4),\r\n    );\r\n  }\r\n\r\n  &.mina {\r\n    background: linear-gradient(65deg, #E94489 2%, #F8C8C5 98%) 0 0 / 100% 100%;\r\n    background-clip: text;\r\n  }\r\n\r\n  &::before {\r\n    content: '';\r\n    @include position.absolute-fill;\r\n    background: linear-gradient(75deg, #4A9AC7 5%, #F148CC 95%) 0 0 / 200% 100%;\r\n    border-radius: 100px;\r\n    opacity: 0;\r\n    @include transition.apply((background-position, 1.5s), opacity);\r\n    z-index: -1;\r\n  }\r\n\r\n  &.mina::before {\r\n    background: linear-gradient(65deg, #E94489 2%, #F8C8C5 98%) 0 0 / 100% 100%;\r\n  }\r\n\r\n  @include aria.outline($radius: 100px);\r\n\r\n  &:hover {\r\n    color: colors.$white;\r\n    background-clip: border-box;\r\n\r\n    &::before {\r\n      background-position: 100% 0;\r\n      opacity: 0.65;\r\n    }\r\n\r\n    &.light::after {\r\n      @include aria.outline-hover;\r\n    }\r\n\r\n    &.dark::after {\r\n      @include aria.outline-hover($color: colors.$white);\r\n    }\r\n  }\r\n\r\n  &:focus {\r\n    &.light::after, &.dark::after {\r\n      @include aria.outline-show;\r\n    }\r\n  }\r\n\r\n  span, strong {\r\n    display: inline-block;\r\n  }\r\n\r\n  strong {\r\n    font-weight: 600;\r\n  }\r\n}\r\n","////\r\n/// @group spacing\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'functions/list';\r\n\r\n@mixin -spacing(\r\n  $prop,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('margin' 'padding', $prop) {\r\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\r\n  }\r\n\r\n  @if $top and $right and $bottom and $left { // all directions specified\r\n    @if $right == $left {\r\n      @if $top == $bottom {\r\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\n    }\r\n  } @else { // not all directions specified\r\n    @if $top {\r\n      #{$prop}-top: $top;\r\n    }\r\n\r\n    @if $right {\r\n      #{$prop}-right: $right;\r\n    }\r\n\r\n    @if $bottom {\r\n      #{$prop}-bottom: $bottom;\r\n    }\r\n\r\n    @if $left {\r\n      #{$prop}-left: $left;\r\n    }\r\n  }\r\n}\r\n\r\n// margin\r\n\r\n@mixin margin(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: margin,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center($vertical: null) {\r\n  @include margin($x: auto, $y: $vertical);\r\n}\r\n\r\n@mixin margin-middle($horizontal: null) {\r\n  @include margin($x: $horizontal, $y: auto);\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-square($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin($all: auto);\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin($all: 0);\r\n}\r\n\r\n// padding\r\n\r\n@mixin padding(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: padding,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin padding-xy($x: null, $y: null) {\r\n  @include padding($x: $x, $y: $y);\r\n}\r\n\r\n@mixin padding-axis($horizontal: null, $vertical: null) {\r\n  @include padding($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin padding-all($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n@mixin padding-square($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n@mixin padding-none {\r\n  @include padding($all: 0);\r\n}\r\n","////\r\n/// @group font\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:meta';\r\n@use 'sass:map';\r\n\r\n@mixin apply($font, $overrides: null) {\r\n  $props: (\r\n    'font-family',\r\n    'font-stretch',\r\n    'font-weight',\r\n  );\r\n\r\n  @each $prop in $props {\r\n    $value: map.get($font, $prop);\r\n\r\n    @if meta.type-of($overrides) == map and map.has-key($overrides, $prop) {\r\n      $value: map.get($overrides, $prop);\r\n    }\r\n\r\n    @if $value {\r\n      #{$prop}: $value;\r\n    } @else {\r\n      @warn 'Font prop `#{$prop}` was ignored because no value was set.';\r\n    }\r\n  }\r\n}\r\n","$black: #000000;\r\n$white: #FFFFFF;\r\n\r\n$gray-lighter: #EEEEEE; // MD Gray 200\r\n$gray-light: #BDBDBD; // MD Gray 400\r\n$gray: #9E9E9E; // MD Gray 500\r\n$gray-dark: #424242; // MD Gray 800\r\n$gray-darker: #212121; // MD Gray 900\r\n$gray-darkest: #121212;\r\n\r\n$red: #F44336; // MD Red 500\r\n$green: #4CAF50; // MD Green 500\r\n$blue: #2196F3; // MD Blue 500\r\n\r\n$pink: #E91E63; // MD Pink 500\r\n$orange: #FF9800; // MD Orange 500\r\n$cyan: #00ACC1; // MD Cyan 500\r\n\r\n$transparent-black: rgba(0, 0, 0, 0);\r\n$transparent-white: rgba(255, 255, 255, 0);\r\n$transparent: $transparent-white;\r\n\r\n$showdown-background-light: #EEF2F5;\r\n$showdown-background-dark: #444444;\r\n","////\r\n/// @group transition\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:list';\r\n@use 'sass:meta';\r\n@use 'config/animations';\r\n\r\n@mixin apply($props...) {\r\n  $transitions: ();\r\n\r\n  @for $i from 1 through list.length($props) {\r\n    $prop: list.nth($props, $i);\r\n\r\n    $name: $prop;\r\n    $duration: animations.$transition-duration;\r\n    $function: animations.$transition-function;\r\n\r\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\r\n      $name: list.nth($prop, 1);\r\n\r\n      @if list.nth($prop, 2) {\r\n        $duration: list.nth($prop, 2);\r\n      }\r\n\r\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\r\n        $function: list.nth($prop, 3);\r\n      }\r\n    }\r\n\r\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\r\n  }\r\n\r\n  @if list.length($transitions) > 0 {\r\n    transition: #{list.zip($transitions)};\r\n  }\r\n}\r\n","////\r\n/// @group aria\r\n/// @access public\r\n/// @author Keith Choison <keith@tize.io>\r\n////\r\n\r\n@use 'sass:math';\r\n@use 'config/colors';\r\n@use 'functions/color';\r\n@use 'position';\r\n@use 'transition';\r\n\r\n///\r\n/// Includes styling for a pseudo-element that displays an outline primarily for accessibility purposes.\r\n/// Requires at least one unusued pseudo-element (i.e, `::before` or `::after`) in the element this mixin is applied to.\r\n///\r\n/// @param {string} $position [relative] - Position of the outline. Specifying `null` will output no `position` property.\r\n/// @param {string} $pseudo [after] - Pseudo-element to use for displaying the outline. Can be `before` or `after`.\r\n/// @param {number} $offset [0] - Spacing between the container and the outline. Works just like the CSS `outline-offset` property.\r\n/// @param {number} $width [2px] - Width (thickness) of the outline. Works just like the CSS `outline-width` and `border-width` properties.\r\n/// @param {string} $style [solid] - Line style of the outline. Works just like the CSS `outline-style` and `border-style` properties.\r\n/// @param {string} $color [colors.$blue] - Color of the outline. Works just like the CSS `outline-color` and `border-color` properties.\r\n/// @param {number} $radius - Optional border radius of the outline. Works just like the CSS `border-radius` property.\r\n/// @param {number} $opacity [0] - Initial opacity of the outline. Set to `null` to not use opacity as the transition property (`border-color` will be used instead).\r\n/// @param {number} $z-index - Optional z-index value of the pseudo-element.\r\n///\r\n@mixin outline(\r\n  $position: relative,\r\n  $pseudo: after,\r\n  $offset: 4px,\r\n  $width: 2px,\r\n  $style: solid,\r\n  $color: colors.$blue,\r\n  $radius: null,\r\n  $opacity: 0,\r\n  $z-index: null,\r\n) {\r\n  @if $position {\r\n    position: $position;\r\n  }\r\n\r\n  outline: none;\r\n\r\n  &::#{$pseudo} {\r\n    content: '';\r\n    @include position.absolute($all: -$offset);\r\n    border: $width $style $color;\r\n    opacity: $opacity;\r\n    @include transition.apply(border-color, opacity);\r\n    pointer-events: none;\r\n\r\n    @if $radius {\r\n      @if math.abs($offset) > 0 {\r\n        $radi