\r\n\r\n  box-shadow: (\r\n    light: (\r\n      0 0 1px color.alpha(colors.$black, 0.3),\r\n      0 0 2px color.alpha(colors.$gray-darker, 0.3),\r\n    ),\r\n\r\n    dark: (\r\n      0 0 1px color.alpha(colors.$white, 0.5),\r\n      0 0 2px color.alpha(colors.$black, 0.3),\r\n    ),\r\n  )\r\n);\r\n\r\n$handle: (\r\n  size: map.get($track, height) - map.get($track, gutter),\r\n\r\n  background-color: (\r\n    default: (\r\n      light: colors.$white,\r\n      dark: colors.$white,\r\n    ),\r\n\r\n    disabled: (\r\n      light: colors.$gray-light,\r\n      dark: colors.$white,\r\n    ),\r\n  ),\r\n\r\n  box-shadow: (\r\n    light: (\r\n      0 0 1px color.alpha(colors.$black, 0.3),\r\n      0 0 3px color.alpha(colors.$gray-darker, 0.25),\r\n    ),\r\n\r\n    dark: (\r\n      0 0 1px color.alpha(colors.$white, 0.3),\r\n      0 0 3px color.alpha(colors.$black, 0.25),\r\n    ),\r\n  ),\r\n\r\n  opacity: (\r\n    read-only: 0.5,\r\n    disabled: 0.5,\r\n  ),\r\n\r\n  transition-duration: 125ms,\r\n);\r\n\r\n.container {\r\n  position: relative;\r\n}\r\n\r\n.field {\r\n  @include flex.row;\r\n  // min-height: map.get($field, min-height);\r\n  @include spacing.padding-xy($x: map.get($field, padding-x), $y: map.get($field, padding-y));\r\n  font-weight: map.get($label, font-weight);\r\n  font-size: map.get($label, font-size);\r\n  border-radius: map.get($field, border-radius);\r\n  outline: none;\r\n  @include transition.apply(color, opacity);\r\n  cursor: pointer;\r\n\r\n  .light & {\r\n    color: map.get($label, color, default, light);\r\n  }\r\n\r\n  .dark & {\r\n    color: map.get($label, color, default, dark);\r\n  }\r\n\r\n  &:not(.readOnly):hover {\r\n    .light & {\r\n      color: map.get($label, color, hover, light);\r\n    }\r\n\r\n    .dark & {\r\n      color: map.get($label, color, hover, dark);\r\n    }\r\n  }\r\n\r\n  &.readOnly {\r\n    cursor: default;\r\n\r\n    .light & {\r\n      color: map.get($label, color, read-only, light);\r\n    }\r\n\r\n    .dark & {\r\n      color: map.get($label, color, read-only, dark);\r\n    }\r\n  }\r\n\r\n  &.disabled {\r\n    opacity: map.get($field, opacity-disabled);\r\n    pointer-events: none;\r\n  }\r\n\r\n  & > * {\r\n    align-self: center;\r\n  }\r\n\r\n  input {\r\n    pointer-events: none;\r\n  }\r\n}\r\n\r\n.label {\r\n  display: block;\r\n  @include spacing.margin($left: map.get($label, spacing));\r\n  color: inherit;\r\n  user-select: none;\r\n}\r\n\r\n.track {\r\n  position: relative;\r\n  @include flex.row;\r\n  @include spacing.padding-all(map.get($track, gutter));\r\n  border-radius: map.get($field, border-radius);\r\n  // @include transition.apply(box-shadow);\r\n\r\n  // .light & {\r\n  //   box-shadow: map.get($track, box-shadow, light);\r\n  // }\r\n\r\n  // .dark & {\r\n  //   box-shadow: map.get($track, box-shadow, dark);\r\n  // }\r\n}\r\n\r\n.backdrop {\r\n  @include position.absolute-all(map.get($backdrop, gutter));\r\n  display: block;\r\n  border-radius: map.get($field, border-radius);\r\n  @include transition.apply(box-shadow);\r\n  overflow: hidden;\r\n  // z-index: -1;\r\n\r\n  .light & {\r\n    box-shadow: map.get($track, box-shadow, light);\r\n  }\r\n\r\n  .dark & {\r\n    box-shadow: map.get($track, box-shadow, dark);\r\n  }\r\n}\r\n\r\n.innerBackdrop {\r\n  display: block;\r\n  width: 100%;\r\n  height: 100%;\r\n  border-radius: map.get($field, border-radius);\r\n  @include transition.apply(background-color);\r\n\r\n  .light & {\r\n    background-color: map.get($backdrop, background-color, default, light);\r\n  }\r\n\r\n  .dark & {\r\n    background-color: map.get($backdrop, background-color, default, dark);\r\n  }\r\n\r\n  .selected & {\r\n    .light & {\r\n      background-color: map.get($backdrop, background-color, selected, light);\r\n    }\r\n\r\n    .dark & {\r\n      background-color: map.get($backdrop, background-color, selected, dark);\r\n    }\r\n  }\r\n}\r\n\r\n// otherwise, the handle can be dragged into the padding\r\n.trackContainer {\r\n  @include flex.row;\r\n  width: 100%;\r\n}\r\n\r\n.handle {\r\n  width: map.get($handle, size);\r\n  height: map.get($handle, size);\r\n  background: none;\r\n  border: none;\r\n  border-radius: map.get($field, border-radius);\r\n  outline: none;\r\n  @include transition.apply(\r\n    background-color,\r\n    box-shadow,\r\n    opacity,\r\n    (transform, map.get($handle, transition-duration)),\r\n  );\r\n  z-index: 1;\r\n  cursor: grab;\r\n\r\n  .light & {\r\n    background-color: map.get($handle, background-color, default, light);\r\n    box-shadow: map.get($handle, box-shadow, light);\r\n  }\r\n\r\n  .dark & {\r\n    background-color: map.get($handle, background-color, default, dark);\r\n    box-shadow: map.get($handle, box-shadow, dark);\r\n  }\r\n\r\n  &.dragging {\r\n    cursor: grabbing;\r\n  }\r\n\r\n  &.readOnly {\r\n    opacity: map.get($handle, opacity, read-only);\r\n    cursor: default;\r\n  }\r\n\r\n  .disabled & {\r\n    box-shadow: none;\r\n    opacity: map.get($handle, opacity, disabled);\r\n    cursor: not-allowed;\r\n\r\n    .light & {\r\n      background-color: map.get($handle, background-color, disabled, light);\r\n    }\r\n\r\n    .dark & {\r\n      background-color: map.get($handle, background-color, disabled, dark);\r\n    }\r\n  }\r\n}\r\n","////\r\n/// @group flex\r\n/// @author Keith Choison\r\n////\r\n\r\n@mixin -flex($direction: null, $justify: null, $align: null, $inline: false) {\r\n  display: if($inline, inline-flex, flex);\r\n\r\n  @if $direction and $direction != row {\r\n    flex-direction: $direction;\r\n  }\r\n\r\n  @if $justify and $justify != flex-start {\r\n    justify-content: $justify;\r\n  }\r\n\r\n  @if $align and $align != stretch {\r\n    align-items: $align;\r\n  }\r\n\r\n  // @if $inline {\r\n  //   vertical-align: middle;\r\n  // }\r\n}\r\n\r\n// rows\r\n\r\n@mixin row($justify: null, $align: null, $inline: false) {\r\n  @include -flex(row, $justify, $align, $inline);\r\n}\r\n\r\n@mixin row-start($inline: false) {\r\n  @include row(flex-start, center, $inline);\r\n}\r\n\r\n@mixin row-center($inline: false) {\r\n  @include row(center, center, $inline);\r\n}\r\n\r\n@mixin row-end($inline: false) {\r\n  @include row(flex-end, center, $inline);\r\n}\r\n\r\n@mixin row-between($inline: false) {\r\n  @include row(space-between, center, $inline);\r\n}\r\n\r\n@mixin row-around($inline: false) {\r\n  @include row(space-around, center, $inline);\r\n}\r\n\r\n// columns\r\n\r\n@mixin column($justify: null, $align: null, $inline: false) {\r\n  @include -flex(column, $justify, $align, $inline);\r\n}\r\n\r\n@mixin column-start($inline: false) {\r\n  @include column(flex-start, center, $inline);\r\n}\r\n\r\n@mixin column-center($inline: false) {\r\n  @include column(center, center, $inline);\r\n}\r\n\r\n@mixin column-end($inline: false) {\r\n  @include column(flex-end, center, $inline);\r\n}\r\n\r\n@mixin column-between($inline: false) {\r\n  @include column(space-between, center, $inline);\r\n}\r\n\r\n@mixin column-around($inline: false) {\r\n  @include column(space-around, center, $inline);\r\n}\r\n","////\r\n/// @group spacing\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'functions/list';\r\n\r\n@mixin -spacing(\r\n  $prop,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('margin' 'padding', $prop) {\r\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\r\n  }\r\n\r\n  @if $top and $right and $bottom and $left { // all directions specified\r\n    @if $right == $left {\r\n      @if $top == $bottom {\r\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\