  font-weight: 500;\r\n  }\r\n}\r\n\r\n.format {\r\n  // max-width: 100%;\r\n  @include spacing.margin($bottom: 2px);\r\n  font-size: 10px;\r\n  letter-spacing: 0.25px;\r\n  text-transform: uppercase;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  opacity: 0.6;\r\n  overflow: hidden;\r\n}\r\n\r\n.honkName {\r\n  // @include font.apply(fonts.$mono);\r\n  font-weight: 500;\r\n  font-size: 12px;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  opacity: 0.4;\r\n  overflow: hidden;\r\n  @include transition.apply(opacity);\r\n\r\n  .saved & {\r\n    opacity: 1;\r\n  }\r\n}\r\n\r\n.players {\r\n  @include flex.row-start;\r\n  // max-width: 100%;\r\n}\r\n\r\n.username {\r\n  // max-width: 44%;\r\n  @include flex.row($align: center);\r\n  font-weight: 500;\r\n  font-size: 12px;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  @include transition.apply(color);\r\n}\r\n\r\n.usernameIcon {\r\n  width: 12px;\r\n  min-width: 12px;\r\n  height: 12px;\r\n  min-height: 12px;\r\n  @include spacing.margin($left: 2px);\r\n  color: inherit;\r\n  transform: scale(1.1);\r\n}\r\n\r\n.versus {\r\n  @include spacing.padding($x: 5px);\r\n  font-weight: 600;\r\n  font-size: 9px;\r\n  text-transform: uppercase;\r\n  opacity: 0.6;\r\n\r\n  &.noPlayerName {\r\n    @include spacing.padding($left: 0);\r\n  }\r\n}\r\n\r\n.morePlayers {\r\n  @include spacing.margin($left: 3px);\r\n  font-weight: 500;\r\n  font-size: 9px;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  opacity: 0.6;\r\n  overflow: hidden;\r\n}\r\n\r\n@keyframes undo-overlay-fade-in {\r\n  0% {\r\n    opacity: 0;\r\n  }\r\n\r\n  100% {\r\n    opacity: 1;\r\n  }\r\n}\r\n\r\n.undoOverlay {\r\n  @include position.absolute-fill;\r\n  @include flex.row-center;\r\n  @include font.apply(fonts.$primary, ( font-weight: 500 ));\r\n  font-size: 10px;\r\n  text-transform: uppercase;\r\n  backdrop-filter: blur(4px);\r\n  border-radius: 12px;\r\n  animation: undo-overlay-fade-in ease 300ms;\r\n  @include transition.apply(color);\r\n\r\n  .light & {\r\n    color: color.shade(colors.$red, 16%);\r\n  }\r\n\r\n  .dark & {\r\n    color: colors.$red;\r\n  }\r\n}\r\n\r\n.removeButton {\r\n  @include position.absolute($top: 24px, $right: 12px);\r\n  width: 16px;\r\n  height: 16px;\r\n  border-radius: 100px;\r\n  opacity: 0;\r\n  @include transition.apply(top, color, opacity);\r\n  pointer-events: none;\r\n\r\n  i {\r\n    font-size: 16px;\r\n  }\r\n\r\n  div.container:not(.removing):hover &, div.container:not(.removing):focus & {\r\n    top: 10px;\r\n    opacity: 1;\r\n    pointer-events: all;\r\n  }\r\n\r\n  .light & {\r\n    color: color.alpha(colors.$black, 0.4);\r\n  }\r\n\r\n  .dark & {\r\n    color: color.alpha(colors.$white, 0.4);\r\n  }\r\n\r\n  @include aria.outline(\r\n    $position: null,\r\n    $offset: 3px,\r\n    $radius: 100px,\r\n  );\r\n\r\n  &:hover {\r\n    .light & {\r\n      color: color.alpha(color.shade(colors.$red, 12%), 0.94);\r\n      // background-color: color.alpha(colors.$black, 0.12);\r\n    }\r\n\r\n    .dark & {\r\n      color: color.alpha(colors.$red, 0.94);\r\n      // background-color: color.alpha(colors.$white, 0.12);\r\n    }\r\n\r\n    &::after {\r\n      .light & {\r\n        @include aria.outline-hover;\r\n      }\r\n\r\n      .dark & {\r\n        @include aria.outline-hover($color: colors.$white);\r\n      }\r\n    }\r\n  }\r\n\r\n  &:focus::after {\r\n    .light &, .dark & {\r\n      @include aria.outline-show;\r\n    }\r\n  }\r\n}\r\n","////\r\n/// @group flex\r\n/// @author Keith Choison\r\n////\r\n\r\n@mixin -flex($direction: null, $justify: null, $align: null, $inline: false) {\r\n  display: if($inline, inline-flex, flex);\r\n\r\n  @if $direction and $direction != row {\r\n    flex-direction: $direction;\r\n  }\r\n\r\n  @if $justify and $justify != flex-start {\r\n    justify-content: $justify;\r\n  }\r\n\r\n  @if $align and $align != stretch {\r\n    align-items: $align;\r\n  }\r\n\r\n  // @if $inline {\r\n  //   vertical-align: middle;\r\n  // }\r\n}\r\n\r\n// rows\r\n\r\n@mixin row($justify: null, $align: null, $inline: false) {\r\n  @include -flex(row, $justify, $align, $inline);\r\n}\r\n\r\n@mixin row-start($inline: false) {\r\n  @include row(flex-start, center, $inline);\r\n}\r\n\r\n@mixin row-center($inline: false) {\r\n  @include row(center, center, $inline);\r\n}\r\n\r\n@mixin row-end($inline: false) {\r\n  @include row(flex-end, center, $inline);\r\n}\r\n\r\n@mixin row-between($inline: false) {\r\n  @include row(space-between, center, $inline);\r\n}\r\n\r\n@mixin row-around($inline: false) {\r\n  @include row(space-around, center, $inline);\r\n}\r\n\r\n// columns\r\n\r\n@mixin column($justify: null, $align: null, $inline: false) {\r\n  @include -flex(column, $justify, $align, $inline);\r\n}\r\n\r\n@mixin column-start($inline: false) {\r\n  @include column(flex-start, center, $inline);\r\n}\r\n\r\n@mixin column-center($inline: false) {\r\n  @include column(center, center, $inline);\r\n}\r\n\r\n@mixin column-end($inline: false) {\r\n  @include column(flex-end, center, $inline);\r\n}\r\n\r\n@mixin column-between($inline: false) {\r\n  @include column(space-between, center, $inline);\r\n}\r\n\r\n@mixin column-around($inline: false) {\r\n  @include column(space-around, center, $inline);\r\n}\r\n","////\r\n/// @group spacing\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'functions/list';\r\n\r\n@mixin -spacing(\r\n  $prop,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('margin' 'padding', $prop) {\r\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\r\n  }\r\n\r\n  @if $top and $right and $bottom and $left { // all directions specified\r\n    @if $right == $left {\r\n      @if $top == $bottom {\r\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\n    }\r\n  } @else { // not all directions specified\r\n    @if $top {\r\n      #{$prop}-top: $top;\r\n    }\r\n\r\n    @if $right {\r\n      #{$prop}-right: $right;\r\n    }\r\n\r\n    @if $bottom {\r\n      #{$prop}-bottom: $bottom;\r\n    }\r\n\r\n    @if $left {\r\n      #{$prop}-left: $left;\r\n    }\r\n  }\r\n}\r\n\r\n// margin\r\n\r\n@mixin margin(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: margin,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center($vertical: null) {\r\n  @include margin($x: auto, $y: $vertical);\r\n}\r\n\r\n@mixin margin-middle($horizontal: null) {\r\n  @include margin($x: $horizontal, $y: auto);\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-square($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin($all: auto);\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin($all: 0);\r\n}\r\n\r\n// padding\r\n\r\n@mixin padding(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: padding,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin padding-xy($x: null, $y: null) {\r\n  @include padding($x: $x, $y: $y);\r\n}\r\n\r\n@mixin padding-axis($horizontal: null, $vertical: null) {\r\n  @include padding($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin padding-all($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n@mixin padding-square($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n@mixin padding-none {\r\n  @include padding($all: 0);\r\n}\r\n","////\r\n/// @group font\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:meta';\r\n@use 'sass:map';\r\n\r\n@mixin apply($font, $overrides: null) {\r\n  $props: (\r\n    'font-family',\r\n    'font-stretch',\r\n    'font-weight',\r\n  );\r\n\r\n  @each $prop in $props {\r\n    $value: map.get($font, $prop);\r\n\r\n    @if meta.type-of($overrides) == map and map.has-key($overrides, $prop) {\r\n      $value: map.get($overrides, $prop);\r\n    }\r\n\r\n    @if $value {\r\n      #{$prop}: $value;\r\n    } @else {\r\n      @warn 'Font prop `#{$prop}` was ignored because no value was set.';\r\n    }\r\n  }\r\n}\r\n","////\r\n/// @group transition\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:list';\r\n@use 'sass:meta';\r\n@use 'config/animations';\r\n\r\n@mixin apply($props...) {\r\n  $transitions: ();\r\n\r\n  @for $i from 1 through list.length($props) {\r\n    $prop: list.nth($props, $i);\r\n\r\n    $name: $prop;\r\n    $duration: animations.$transition-duration;\r\n    $function: animations.$transition-function;\r\n\r\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\r\n      $name: list.nth($prop, 1);\r\n\r\n      @if list.nth($prop, 2) {\r\n        $duration: list.nth($prop, 2);\r\n      }\r\n\r\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\r\n        $function: list.nth($prop, 3);\r\n      }\r\n    }\r\n\r\n    $transitions: list.append($transitions, '#{