anded & {\r\n    grid-area: 3 / 1;\r\n    @include spacing.margin($top: 4px, $bottom: 1px, $left: 10px);\r\n  }\r\n}\r\n\r\n.leftFieldInput {\r\n  .expanded & {\r\n    grid-area: 4 / 1;\r\n    @include spacing.margin($top: 1px);\r\n  }\r\n}\r\n\r\n.weatherInput {\r\n  align-self: flex-start;\r\n  // max-width: 152px;\r\n  @include spacing.margin($x: auto);\r\n\r\n  .expanded & {\r\n    grid-area: 2 / 1;\r\n    @include spacing.margin($top: 4px, $right: 0, $bottom: 10px, $left: 12px);\r\n  }\r\n}\r\n\r\n.terrainInput {\r\n  align-self: flex-start;\r\n  // max-width: 152px;\r\n  @include spacing.margin($x: auto);\r\n\r\n  .expanded & {\r\n    grid-area: 2 / 2;\r\n    @include spacing.margin($top: 4px, $right: 12px, $bottom: 10px, $left: 0);\r\n  }\r\n}\r\n\r\n.rightFieldLabel {\r\n  @include spacing.margin($right: 8px);\r\n\r\n  &.spectating {\r\n    @include spacing.margin($right: 4px);\r\n  }\r\n\r\n  .expanded & {\r\n    grid-area: 3 / 2;\r\n    @include spacing.margin($top: 4px, $right: 10px, $bottom: 1px);\r\n  }\r\n}\r\n\r\n.rightFieldInput {\r\n  .expanded & {\r\n    grid-area: 4 / 2;\r\n    @include spacing.margin($top: 1px);\r\n  }\r\n}\r\n\r\nbutton.toggleButton {\r\n  min-width: 60px;\r\n  @include spacing.margin($all: 1px);\r\n  @include spacing.padding($x: 4px);\r\n  font-size: 10px;\r\n  text-transform: none;\r\n}\r\n\r\n.tooltipContent {\r\n  text-align: center;\r\n  white-space: normal;\r\n  user-select: none;\r\n}\r\n\r\n.descTooltip {\r\n  max-width: 165px;\r\n}\r\n","////\r\n/// @group spacing\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'functions/list';\r\n\r\n@mixin -spacing(\r\n  $prop,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('margin' 'padding', $prop) {\r\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\r\n  }\r\n\r\n  @if $top and $right and $bottom and $left { // all directions specified\r\n    @if $right == $left {\r\n      @if $top == $bottom {\r\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\n    }\r\n  } @else { // not all directions specified\r\n    @if $top {\r\n      #{$prop}-top: $top;\r\n    }\r\n\r\n    @if $right {\r\n      #{$prop}-right: $right;\r\n    }\r\n\r\n    @if $bottom {\r\n      #{$prop}-bottom: $bottom;\r\n    }\r\n\r\n    @if $left {\r\n      #{$prop}-left: $left;\r\n    }\r\n  }\r\n}\r\n\r\n// margin\r\n\r\n@mixin margin(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: margin,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center($vertical: null) {\r\n  @include margin($x: auto, $y: $vertical);\r\n}\r\n\r\n@mixin margin-middle($horizontal: null) {\r\n  @include margin($x: $horizontal, $y: auto);\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-square($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin($all: auto);\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin($all: 0);\r\n}\r\n\r\n// padding\r\n\r\n@mixin padding(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r